// Turn one Gmail Trigger item into the fields the rest of the workflow uses.
// The Gmail node can hand us two different shapes:
//   (a) structured: { from: {value:[{address,name}]}, to: {...}, subject: "..", text: ".." }
//   (b) raw Gmail API: { payload: { headers: [{name,value}], parts: [..] } }
// We accept both, so the workflow keeps working if the trigger output ever changes.
const m = $input.first().json;
const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);

function rawHeader(name) {
  const hs = (m.payload && m.payload.headers) ? m.payload.headers : [];
  for (const h of hs) {
    if (String(h.name).toLowerCase() === String(name).toLowerCase()) return String(h.value);
  }
  return "";
}

function addressOf(value) {
  if (!value) return "";
  if (typeof value === "string") {
    const inside = value.match(/<([^>]+)>/);
    return (inside ? inside[1] : value).trim();
  }
  if (typeof value === "object" && Array.isArray(value.value) && value.value.length > 0) {
    const first = value.value[0];
    if (first && first.address) return String(first.address).trim();
  }
  return "";
}

function decodeBase64(data) {
  if (!data) return "";
  const safe = String(data).replace(/-/g, "+").replace(/_/g, "/");
  return Buffer.from(safe, "base64").toString("utf8");
}

function findPlainText(payload) {
  if (!payload) return "";
  if (payload.mimeType === "text/plain" && payload.body && payload.body.data) {
    return decodeBase64(payload.body.data);
  }
  const parts = payload.parts || [];
  for (const p of parts) {
    const found = findPlainText(p);
    if (found) return found;
  }
  if (payload.body && payload.body.data) return decodeBase64(payload.body.data);
  return "";
}

let from = addressOf(m.from) || rawHeader("From");
let to = addressOf(m.to) || rawHeader("Delivered-To") || rawHeader("To");
const subject = (typeof m.subject === "string" && m.subject) ? m.subject : rawHeader("Subject");

let body = "";
if (typeof m.text === "string" && m.text) body = m.text;
if (!body) body = findPlainText(m.payload);
if (!body && typeof m.snippet === "string") body = m.snippet;

const clean = body.split(CR).join(NL).split(NL)
  .filter(function (line) { return line.trim().charAt(0) !== ">"; })
  .join(NL).trim();

// Some mail clients send subject-only emails. If the body is empty, use the
// subject as the question instead of replying with a useless greeting.
let question = clean;
if (!question) question = String(subject || "");

return [{ json: {
  question: question.slice(0, 1500),
  from: String(from),
  subject: String(subject),
  to: String(to),
  threadId: m.threadId || "",
  messageId: m.id || "",                      // Gmail API id - what markAsRead needs
  rfcMessageId: m.messageId || ""             // RFC header id, for threading/debug
} }];
